"""EX-10 B3 offline Ed25519 witness core; no service or key management.

Trust material is supplied by an externally approved caller. Neither receipts
nor SQLite authorize a public key. A signer is injected; private keys are never
serialized, loaded from custody, generated by this module or stored here.
"""

from __future__ import annotations

import copy
import hashlib
from dataclasses import dataclass
from datetime import timedelta
from typing import Protocol

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey

from . import ex10_authority_sqlite as codec

