SCHEMAS = codec.json.loads(_APPROVED_WITNESS_SCHEMAS_JSON)
RECEIPT_SCHEMA = "s11-ex10-authority-witness-receipt-v1"
HEAD_SCHEMA = "s11-ex10-authority-witness-head-v1"
DOMAINS = {
    RECEIPT_SCHEMA: b"S11-EX10-B3-WITNESS-RECEIPT-V1\n",
    HEAD_SCHEMA: b"S11-EX10-B3-WITNESS-HEAD-V1\n",
}


class Signer(Protocol):
    """Independent signer interface. Implementations stay outside this core."""

    def sign(self, data: bytes) -> bytes: ...


@dataclass(frozen=True, slots=True)
class TrustPin:
    """Injected external public trust material; no self-approval from a ledger."""

    canonical_record: bytes

    def __post_init__(self):
        record = codec.parse_canonical(self.canonical_record)
        codec.validate_schema(record, SCHEMAS["trust_root"])
        raw = bytes.fromhex(record["public_key_hex"])
        codec.require(
            len(raw) == 32 and hashlib.sha256(raw).hexdigest() == record["fingerprint"],
            "TRUST_UNAPPROVED",
        )
        _validate_reference(record["approval_reference"])
        _validate_reference(record["transport_identity_reference"])
        if record["key_transition_reference"] is not None:
            _validate_reference(record["key_transition_reference"])
        codec.require(
            record["retirement_revision"] is None
            or record["retirement_revision"] >= record["activation_revision"],
            "TRUST_UNAPPROVED",
        )

    @property
    def record(self):
        return codec.parse_canonical(self.canonical_record)


def _validate_reference(reference):
    codec.validate_schema(reference, SCHEMAS["external_reference"])
    codec.validate_scalar(reference["path"], {"type": "locator", "not_null": True})
    codec.validate_scalar(reference["schema_version"], {"type": "identifier", "not_null": True})


def _validate_message(record):
    schema = record.get("witness_schema_version") if type(record) is dict else None
    codec.require(schema in DOMAINS, "SCHEMA")
    codec.validate_schema(
        record, SCHEMAS["receipt" if schema == RECEIPT_SCHEMA else "current_head"]
    )
    codec.utc_time(record["created_at"] if schema == RECEIPT_SCHEMA else record["issued_at"])
    if schema == HEAD_SCHEMA:
        start, end = codec.utc_time(record["issued_at"]), codec.utc_time(record["expires_at"])
        codec.require(start < end <= start + timedelta(seconds=240), "EXPIRED_OBSERVATION")
    elif record["revision"] == 0:
        _validate_reference(record["genesis"]["g0_a3_approval_reference"])
    return schema


def build_witness_payload(fields):
    """Build an exact receipt payload; signing is separate and injected."""
    codec.require(type(fields) is dict and "signature" not in fields, "SCHEMA")
    payload = copy.deepcopy(fields)
    _validate_message({**payload, "signature": "0" * 128})
    codec.require(payload["witness_schema_version"] == RECEIPT_SCHEMA, "SCHEMA")
    return payload


def _message(record):
    return DOMAINS[record["witness_schema_version"]] + codec.canonical_bytes(
        {k: v for k, v in record.items() if k != "signature"}
    )


def sign_witness(payload, signer: Signer):
    """Sign a receipt with an injected signer; no key creation/serialization."""
    built = build_witness_payload(payload)
    signature = signer.sign(_message(built))
    codec.require(type(signature) is bytes and len(signature) == 64, "SIGNATURE_INVALID")
    result = {**built, "signature": signature.hex()}
    _validate_message(result)
    return result


def _sign_current_head(fields, signer: Signer):
    """Synthetic/offline response primitive; not a running witness endpoint."""
    codec.require("signature" not in fields, "SCHEMA")
    _validate_message({**fields, "signature": "0" * 128})
    codec.require(fields["witness_schema_version"] == HEAD_SCHEMA, "SCHEMA")
    signature = signer.sign(_message(fields))
    codec.require(type(signature) is bytes and len(signature) == 64, "SIGNATURE_INVALID")
    return {**copy.deepcopy(fields), "signature": signature.hex()}


def _verify_record(record, trust_pin):
    codec.require(type(trust_pin) is TrustPin, "TRUST_UNAPPROVED")
    _validate_message(record)
    pin = trust_pin.record
    codec.require(
        all(
            record[k] == pin[k]
            for k in ("authority_id", "authority_epoch", "namespace", "key_id", "key_epoch")
        ),
        "TRUST_UNAPPROVED",
    )
    codec.require(record["key_fingerprint"] == pin["fingerprint"], "TRUST_UNAPPROVED")
    codec.require(
        record["revision"] >= pin["activation_revision"]
        and (
            pin["retirement_revision"] is None or record["revision"] <= pin["retirement_revision"]
        ),
        "TRUST_UNAPPROVED",
    )
    try:
        Ed25519PublicKey.from_public_bytes(bytes.fromhex(pin["public_key_hex"])).verify(
            bytes.fromhex(record["signature"]), _message(record)
        )
    except (InvalidSignature, ValueError) as exc:
        raise codec.AuthorityError("SIGNATURE_INVALID") from exc
    return codec.digest(record)


def verify_witness(record, trust_pin):
    codec.require(
        type(record) is dict and record.get("witness_schema_version") == RECEIPT_SCHEMA, "SCHEMA"
    )
    return _verify_record(record, trust_pin)


def verify_chain(records, trust_pins, *, expected_genesis_digest, expected_genesis_binding):
    """Verify all receipts from externally pinned genesis; no local key fallback."""
    codec.require(
        type(records) in (list, tuple) and records and type(expected_genesis_digest) is str,
        "HISTORY_INVALID",
    )
    codec.require(
        type(trust_pins) in (list, tuple) and all(type(p) is TrustPin for p in trust_pins),
        "TRUST_UNAPPROVED",
    )
    pins = {(p.record["key_id"], p.record["key_epoch"]): p for p in trust_pins}
    codec.require(len(pins) == len(trust_pins), "TRUST_UNAPPROVED")
    previous = None
    previous_epoch = None
    _validate_message(records[0])
    authority = records[0]["authority_id"], records[0]["authority_epoch"], records[0]["namespace"]
    operations = set()
    for number, record in enumerate(records):
        _validate_message(record)
        codec.require(
            record["revision"] == number and record["previous_witness_digest"] == previous,
            "FORK_DETECTED",
        )
        codec.require(
            (record["authority_id"], record["authority_epoch"], record["namespace"]) == authority,
            "FORK_DETECTED",
        )
        codec.require(record["operation_id"] not in operations, "FORK_DETECTED")
        operations.add(record["operation_id"])
        pin = pins.get((record["key_id"], record["key_epoch"]))
        codec.require(pin is not None, "TRUST_UNAPPROVED")
        epoch = pin.record["key_epoch"]
        if previous_epoch is not None and epoch != previous_epoch:
            codec.require(
                epoch == previous_epoch + 1
                and pin.record["activation_revision"] == number
                and pin.record["key_transition_reference"] is not None,
                "TRUST_UNAPPROVED",
            )
        previous_epoch = epoch
        previous = verify_witness(record, pin)
        if number == 0:
            codec.require(
                previous == expected_genesis_digest
                and record["genesis"] == expected_genesis_binding,
                "TRUST_UNAPPROVED",
            )
    return previous


@dataclass(frozen=True, slots=True)
class TrustedFloor:
    authority_id: str
    authority_epoch: int
    revision: int
    witness_digest: str

    def __post_init__(self):
        for value, kind in (
            (self.authority_id, "uuid"),
            (self.authority_epoch, "positive_int64"),
            (self.revision, "int64_nonnegative"),
            (self.witness_digest, "sha256"),
        ):
            codec.validate_scalar(value, {"type": kind, "not_null": True})


def _verify_current_head(
    record, trust_pin, *, challenge, now, request_elapsed_seconds, clock_healthy
):
    """Verify an externally obtained nonce response offline; never send requests."""
    codec.require(
        type(record) is dict and record.get("witness_schema_version") == HEAD_SCHEMA, "SCHEMA"
    )
    _verify_record(record, trust_pin)
    codec.validate_scalar(challenge, {"type": "sha256", "not_null": True})
    codec.require(record["challenge"] == challenge, "EXPIRED_OBSERVATION")
    codec.require(
        clock_healthy is True
        and type(request_elapsed_seconds) in (int, float)
        and 0 <= request_elapsed_seconds <= 30,
        "EXPIRED_OBSERVATION",
    )
    current = codec.utc_time(now)
    start, end = codec.utc_time(record["issued_at"]), codec.utc_time(record["expires_at"])
    codec.require(
        start <= current + timedelta(seconds=5)
        and current < end
        and current >= start - timedelta(seconds=5),
        "EXPIRED_OBSERVATION",
    )
    return codec.digest(record)


def _verify_floor(local_revision, local_digest, local_head, records, remote_head, floor):
    codec.require(type(floor) is TrustedFloor, "TRUST_UNAPPROVED")
    codec.require(
        type(local_revision) is int and local_revision >= floor.revision, "ROLLBACK_DETECTED"
    )
    codec.require(
        remote_head["authority_id"] == floor.authority_id
        and remote_head["authority_epoch"] == floor.authority_epoch,
        "TRUST_UNAPPROVED",
    )
    codec.require(
        remote_head["revision"] == local_revision
        and remote_head["ledger_digest"] == local_digest
        and remote_head["witness_digest"] == local_head,
        "ROLLBACK_DETECTED",
    )
    codec.require(
        len(records) > floor.revision
        and codec.digest(records[floor.revision]) == floor.witness_digest,
        "FORK_DETECTED",
    )
